import { useCallback } from 'react';

import { FieldProps } from 'components/Filter/types';
import { usePageFilterData } from 'hooks';
import { Option } from 'models/Filters';

import {
  TimePeriodSelection,
  TimePeriodSelector,
} from '../../../TimePeriodSelector';

export const TimePeriodField = ({
  pageName,
  onValueChange,
  onValuesChange,
  getCurrentValue,
}: FieldProps) => {
  const { dataFilters } = usePageFilterData(pageName);
  const periodTypes = dataFilters?.time_period?.values as Option[] | undefined;
  const maxDtEnd = dataFilters?.time_period?.max_dt_end;
  const selectedType = String(getCurrentValue('period_type') ?? '');
  const selectedDtEnd = getCurrentValue('dt_end') || null;

  const handleChange = useCallback(
    ({ periodType, dtEnd }: TimePeriodSelection) => {
      if (onValuesChange) {
        onValuesChange({
          period_type: periodType,
          dt_end: dtEnd,
        });
        return;
      }

      onValueChange('period_type', { value: periodType, label: periodType });
      onValueChange('dt_end', {
        value: dtEnd,
        label: dtEnd,
      });
    },
    [onValueChange, onValuesChange],
  );

  if (
    !dataFilters?.time_period?.enabled ||
    !periodTypes?.length ||
    !maxDtEnd ||
    !selectedType
  ) {
    return null;
  }

  return (
    <TimePeriodSelector
      periodTypes={periodTypes}
      maxDtEnd={maxDtEnd}
      selectedType={selectedType}
      selectedDtEnd={selectedDtEnd}
      onChange={handleChange}
      variant="modal"
    />
  );
};
